import{f as n,J as d,o as t,c as i,a6 as a,b as s,w as r,a as h,K as l,a7 as c}from"./chunks/framework.Dd1qhYRL.js";const v=JSON.parse('{"title":"Why noorm","description":"noorm is the fifth attempt at one problem. The questions that grew it, the CLI libraries that came first, and what LLMs changed.","frontmatter":{"title":"Why noorm","description":"noorm is the fifth attempt at one problem. The questions that grew it, the CLI libraries that came first, and what LLMs changed."},"headers":[],"relativePath":"why-noorm.md","filePath":"why-noorm.md"}'),m={name:"why-noorm.md"};function p(f,e,u,g,w,b){const o=d("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="why-noorm" tabindex="-1">Why noorm <a class="header-anchor" href="#why-noorm" aria-label="Permalink to “Why noorm”">​</a></h1><p>I stopped using ORMs and needed something to run the SQL. Every other part of noorm answers a question I hit after that.</p><h2 id="which-questions-grew-the-tool" tabindex="-1">Which questions grew the tool? <a class="header-anchor" href="#which-questions-grew-the-tool" aria-label="Permalink to “Which questions grew the tool?”">​</a></h2><p>Each row is a question I hit.</p><table tabindex="0"><thead><tr><th>Question</th><th>What it became</th></tr></thead><tbody><tr><td>How do I run SQL?</td><td><a href="/getting-started/concepts.html">A folder of files</a>, run in path order</td></tr><tr><td>How do I undo one?</td><td><a href="/guide/changes/forward-revert.html">Forward and revert</a> pairs</td></tr><tr><td>How do I test against it?</td><td>A real database behind a <a href="/reference/sdk.html"><code>requireTest</code></a> guard</td></tr><tr><td>How do I write painful DDL and seed data?</td><td><a href="/guide/sql-files/templates.html">Templates</a> that render SQL from YAML, and <a href="/guide/database/transfer.html">transfer</a></td></tr><tr><td>Where does connection configuration live?</td><td><a href="/guide/environments/configs.html">Configs</a> you export to a teammate</td></tr><tr><td>How do I onboard someone onto four environments?</td><td><a href="/guide/environments/stages.html">Stages</a> with required secrets</td></tr><tr><td>Where do team secrets live?</td><td>A <a href="/guide/environments/vault.html">vault</a> table inside the database</td></tr><tr><td>What ran, who ran it, and why did it break?</td><td><a href="/guide/changes/history.html">History</a> with the operator and the error</td></tr><tr><td>How do I re-run objects meant to be re-run?</td><td><code>.txt</code> <a href="/guide/changes/overview.html">manifests</a> that run <code>db/sql/</code> files</td></tr></tbody></table><h2 id="why-is-the-interface-split-in-two" tabindex="-1">Why is the interface split in two? <a class="header-anchor" href="#why-is-the-interface-split-in-two" aria-label="Permalink to “Why is the interface split in two?”">​</a></h2><p>noorm is the fifth attempt. I replaced each of the first three because I needed something more robust, one a new teammate could use without a manual. Then I moved to citty and @clack/prompts, and tried Ink.</p><table tabindex="0"><thead><tr><th>Library, in the order I used it</th><th>What it is</th><th>In noorm today</th></tr></thead><tbody><tr><td>minimist</td><td>argument parser</td><td>no</td></tr><tr><td>cmd-ts</td><td>type-driven argument parser</td><td>no</td></tr><tr><td>oclif</td><td>CLI framework</td><td>no</td></tr><tr><td>citty</td><td>CLI builder</td><td>the commands in <code>src/cli/</code></td></tr><tr><td>@clack/prompts</td><td>interactive prompts</td><td><code>noorm init</code>, <code>noorm change add</code></td></tr><tr><td>Ink</td><td>React for the terminal</td><td>the TUI in <code>src/tui/</code></td></tr></tbody></table><p>Running commands means remembering commands. A screen that shows configs, pending changes, and schema while you decide beats typing a verb and hoping the flags are right.</p><p><code>noorm ui</code> opens the <a href="/tui.html">TUI</a>. The other commands take flags, so they run in scripts and CI (<a href="/headless.html">CLI reference</a>).</p><h2 id="why-templates" tabindex="-1">Why templates? <a class="header-anchor" href="#why-templates" aria-label="Permalink to “Why templates?”">​</a></h2><p>Templates let seed data be written and iterated on, and let YAML become DDL that is miserable to write by hand. SQL Server scheduled jobs are the clearest case: a schedule written semantically renders into the DDL that creates the job. A YAML list of who gets what is readable and diffable, and the <code>GRANT</code> statements it renders into are not.</p><h2 id="why-does-history-record-the-operator-and-the-error" tabindex="-1">Why does history record the operator and the error? <a class="header-anchor" href="#why-does-history-record-the-operator-and-the-error" aria-label="Permalink to “Why does history record the operator and the error?”">​</a></h2><p>Every applied change records its status, when it ran, who ran it, and the error message when it failed. A failure you fixed and re-ran can surface days later. The recorded error shows which run to trace back to, and the operator puts a name on a pattern of failures.</p><p><code>changelog.md</code> in the change folder holds the reason for the change, next to the SQL it justifies. A <code>.txt</code> manifest lists the views, functions, and stored procedures a change re-runs, so fixing a stored procedure is a tracked change.</p><h2 id="how-do-teams-share-environments" tabindex="-1">How do teams share environments? <a class="header-anchor" href="#how-do-teams-share-environments" aria-label="Permalink to “How do teams share environments?”">​</a></h2><p>A config exports from the TUI encrypted to the recipient&#39;s public key, without <code>user</code> and <code>password</code>, so the recipient supplies their own. <a href="/guide/environments/configs.html#how-do-i-share-a-config-with-a-teammate">Configs</a> covers both export paths.</p><p>A template that reads an unset secret fails with <code>Secret &quot;KEY&quot; not found (searched: config-local, global-local, vault)</code>. The vault keeps team secrets encrypted in the database (<code>noorm.vault</code> on PostgreSQL and SQL Server, <code>__noorm_vault__</code> on MySQL and SQLite) at the lowest precedence, so a local value wins.</p><h2 id="what-changed-when-llms-arrived" tabindex="-1">What changed when LLMs arrived? <a class="header-anchor" href="#what-changed-when-llms-arrived" aria-label="Permalink to “What changed when LLMs arrived?”">​</a></h2><p>Writing SQL stopped being the slow part. Reviewing SQL that an agent wrote quickly, confidently, and sometimes wrongly became the slow part. Three additions act before the agent writes, while it writes, and before its SQL runs.</p>',20)),(t(),s(c,null,{default:r(()=>[l(o,{id:"mermaid-223",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20M%5B%22ignatius%20model%22%5D%20--%3E%7Cplan%7C%20A%5BAI%20agent%5D%0A%20%20%20%20K%5B%22noorm%20skill%22%5D%20--%3E%7Cconventions%7C%20A%0A%20%20%20%20A%20--%3E%7CSQL%7C%20G%5B%22access%20role%2C%20dry%20run%2C%3Cbr%2F%3Etyped%20confirmation%22%5D%0A%20%20%20%20G%20--%3E%20DB%5B(database)%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<ul><li><strong>ignatius model</strong>: the cheapest moment to catch a bad schema is before it exists, which became a separate tool, <a href="/modeling/">ignatius</a>.</li><li><strong>noorm skill</strong>: the <a href="/getting-started/installation.html#install-the-agent-skill-optional">agent skill</a> teaches an agent this project&#39;s conventions.</li><li><strong>access role, dry run, typed confirmation</strong>: per-channel <a href="/guide/environments/configs.html#access-roles">access roles</a>, <code>--dry-run</code>, and a typed confirmation on destructive operations.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/getting-started/installation.html">Installation</a></li><li><a href="/getting-started/concepts.html">Concepts</a></li><li><a href="/modeling/">Information modeling</a></li></ul>',3))])}const _=n(m,[["render",p]]);export{v as __pageData,_ as default};
